const cache=new WeakMap();
export function reveal(b,force=false){if(!b.fog)return;if(!force&&b.elapsed-(b.fog.last||0)<.4)return;const explored=new Set(b.fog.explored),visible=new Set();for(const u of [...(['expedition','colony','colony-defense'].includes(b.kind)?[b.start]:[]),...b.units.filter(u=>u.side==='player'&&u.hp>0&&!u.embarked)]){const radius=u.scout?4:3,cx=Math.floor(u.x/5),cy=Math.floor(u.y/5);for(let y=Math.max(0,cy-radius);y<=Math.min(19,cy+radius);y++)for(let x=Math.max(0,cx-radius);x<=Math.min(19,cx+radius);x++)if(Math.hypot(x-cx,y-cy)<=radius){visible.add(y*20+x);explored.add(y*20+x);}}const key=[...visible].sort((a,b)=>a-b).join(',');if(key!==b.fog.key||force){b.fog.visible=[...visible];b.fog.explored=[...explored];b.fog.revision++;b.fog.key=key;}b.fog.last=b.elapsed;}
export function visibleAt(b,x,y,remember=false){if(!b?.fog)return true;let c=cache.get(b.fog);if(!c||c.revision!==b.fog.revision){c={revision:b.fog.revision,visible:new Set(b.fog.visible),explored:new Set(b.fog.explored)};cache.set(b.fog,c);}return(remember?c.explored:c.visible).has(Math.floor(y/5)*20+Math.floor(x/5));}
